<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>News & Updates · TDC TECH</title><link rel="stylesheet" href="/assets/site-theme.css"><script src="/assets/branding.js" defer></script><style>body{margin:0;background:#101116;color:#eee;font:16px system-ui}main,nav{max-width:1000px;margin:auto;padding:24px}a{color:#c0f06d}article{padding:24px;border:1px solid #ffffff22;border-radius:18px;margin:20px 0}img{width:100%;max-height:360px;object-fit:cover;border-radius:12px}.news-body{white-space:pre-wrap;line-height:1.8}</style></head><body><nav><a href="/">TDC TECH</a> / News & Updates</nav><main><h1>News & Updates</h1><div id="news">Loading…</div></main><script>fetch('/api/news.php').then(r=>r.json()).then(d=>{const root=document.getElementById('news');root.replaceChildren();for(const p of d.posts){const article=document.createElement('article');for(const [tag,text] of [['h2',p.title],['small',p.category+' · '+p.created_at],['p',p.body]]){const e=document.createElement(tag);e.textContent=text;if(tag==='p'){e.className='news-body';if(p.body_html)e.innerHTML=p.body_html;}article.append(e)}if(p.cover_url){const img=new Image();img.src=p.cover_url;img.alt=p.title;article.prepend(img)}root.append(article)}if(!d.posts.length)root.textContent='No published news yet.'}).catch(()=>document.getElementById('news').textContent='News could not be loaded. Please retry.');</script></body></html>
